/* cppi::b2cab3644526f2ebd7df7be35849626b92b620caafbd66b4a9e691de5bba1185 */
select business_date as date_, security_id, 'MS757951' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-13' and business_date <= date '2025-06-13' and weight_ndo>0 and id_cppib_index = 'MS757951_GR_USD_0_0' and security_id is not null

/* cppi::b9c64753e58785786e3aca7a11eb961068a111e0657dfa4e604f91dbb1275ad5 */
